={{(() => {
  const q = (value) => "'" + String(value ?? "").replace(/'/g, "'\\''") + "'";
  const clean = (value) => {
    const text = String(value ?? "").trim().replace(/\/+$/, "");
    return text || "/";
  };
  const form = $("On form submission").item.json;

  const src = q(clean(form.sourceFolder));
  const dest = q(clean(form.destinationFolder));
  return [
    "bash <<'BASH'",
    "set -euo pipefail",
    "if ! command -v ditto >/dev/null 2>&1; then",
    "  echo \"ditto is not available. This workflow runs on macOS.\" >&2",
    "  exit 1",
    "fi",
    "src=" + src,
    "dest=" + dest,
    "if [ ! -d \"$src\" ]; then",
    "  echo \"Source folder does not exist: $src\" >&2",
    "  exit 1",
    "fi",
    "if [ -e \"$dest\" ]; then",
    "  echo \"Destination already exists: $dest\" >&2",
    "  exit 1",
    "fi",
    "src_real=$(cd \"$src\" && pwd -P)",
    "mkdir -p \"$(dirname \"$dest\")\"",
    "dest_parent_real=$(cd \"$(dirname \"$dest\")\" && pwd -P)",
    "dest_real=\"$dest_parent_real/$(basename \"$dest\")\"",
    "if [ \"$src_real\" = \"$dest_real\" ]; then",
    "  echo \"Source and destination are the same folder\" >&2",
    "  exit 1",
    "fi",
    "case \"$dest_real/\" in",
    "  \"$src_real/\"*) echo \"Destination is inside the source folder\" >&2; exit 1 ;;",
    "esac",
    "case \"$src_real/\" in",
    "  \"$dest_real/\"*) echo \"Source is inside the destination folder\" >&2; exit 1 ;;",
    "esac",
    "ditto \"$src_real\" \"$dest_real\"",
    "echo \"Copied $src_real to $dest_real\"",
    "BASH",
  ].join("\n");
})()}}

